function gd10(name, formula) {
  const parts = formula.trim().split(/\s+/);
  return { name, formula, args: parts.slice(1) };
}
var FULL_RECT7 = { l: "l", t: "t", r: "r", b: "b" };
function ray(baseX1, baseY1, baseX2, baseY2, apexX, apexY) {
  return {
    commands: [
      { kind: "moveTo", x: baseX1, y: baseY1 },
      { kind: "lnTo", x: baseX2, y: baseY2 },
      { kind: "lnTo", x: apexX, y: apexY },
      { kind: "close" }
    ]
  };
}
function starTrigTable(n) {
  const total = n * 2;
  const step = Math.PI * 2 / total;
  const start = -Math.PI / 2;
  const result = [];
  for (let i2 = 0; i2 < total; i2++) {
    const a = start + i2 * step;
    result.push({
      sin: Math.round(Math.cos(a) * 1e5),
      cos: Math.round(Math.sin(a) * 1e5)
    });
  }
  return result;
}
function buildStarN(n, defaultAdj) {
  const trig = starTrigTable(n);
  const gdLst = [
    gd10("a", `pin 0 adj 50000`),
    gd10("iwd2", "*/ wd2 a 50000"),
    gd10("ihd2", "*/ hd2 a 50000")
  ];
  for (let i2 = 0; i2 < trig.length; i2++) {
    const t = trig[i2];
    const isOuter = i2 % 2 === 0;
    const radiusW = isOuter ? "wd2" : "iwd2";
    const radiusH = isOuter ? "hd2" : "ihd2";
    gdLst.push(gd10(`dx${i2}`, `*/ ${radiusW} ${t.sin} 100000`));
    gdLst.push(gd10(`dy${i2}`, `*/ ${radiusH} ${t.cos} 100000`));
    gdLst.push(gd10(`x${i2}`, `+- hc dx${i2} 0`));
    gdLst.push(gd10(`y${i2}`, `+- vc dy${i2} 0`));
  }
  const commands = [{ kind: "moveTo", x: "x0", y: "y0" }];
  for (let i2 = 1; i2 < trig.length; i2++) {
    commands.push({ kind: "lnTo", x: `x${i2}`, y: `y${i2}` });
  }
  commands.push({ kind: "close" });
  return {
    name: `star${n}`,
    avLst: { adj: defaultAdj },
    gdLst,
    rect: FULL_RECT7,
    pathLst: [{ commands }]
  };
}
