function lookupPresetShape(name) {
  if (!name) {
    return void 0;
  }
  const direct = PRESET_SHAPE_GEOMETRY_TABLE[name];
  if (direct) {
    return direct;
  }
  const lower = name.toLowerCase();
  for (const key2 of Object.keys(PRESET_SHAPE_GEOMETRY_TABLE)) {
    if (key2.toLowerCase() === lower) {
      return PRESET_SHAPE_GEOMETRY_TABLE[key2];
    }
  }
  return void 0;
}
