function getShapeType(shapeType) {
  if (!shapeType) {
    return "rect";
  }
  const normalized = shapeType.toLowerCase();
  if (normalized === "rect") {
    return "rect";
  }
  if (normalized === "roundrect") {
    return "roundRect";
  }
  if (normalized === "ellipse" || normalized === "oval") {
    return "ellipse";
  }
  if (normalized === "cylinder" || normalized === "can") {
    return "cylinder";
  }
  if (normalized === "triangle") {
    return "triangle";
  }
  if (normalized === "diamond") {
    return "diamond";
  }
  if (normalized === "line" || normalized === "lineinv") {
    return "line";
  }
  if (normalized === "rtarrow" || normalized === "rightarrow") {
    return "rtArrow";
  }
  if (normalized === "leftarrow") {
    return "leftArrow";
  }
  if (normalized === "uparrow") {
    return "upArrow";
  }
  if (normalized === "downarrow") {
    return "downArrow";
  }
  if (normalized.includes("connector")) {
    return "connector";
  }
  if (PRESET_SHAPE_CLIP_PATHS[normalized] !== void 0) {
    return "rect";
  }
  return "rect";
}
function filterValidShapeAdjustmentEntries(presetGeometry, adjustments) {
  if (!adjustments) {
    return [];
  }
  const def = lookupPresetShape(presetGeometry);
  const validNames = def ? new Set(Object.keys(def.avLst ?? {})) : void 0;
  return Object.entries(adjustments).filter(
    ([name, value]) => name.trim().length > 0 && Number.isFinite(value) && (!validNames || validNames.has(name))
  );
}
